From 16c7112234e0d52249938e31bafc5710eba840bb Mon Sep 17 00:00:00 2001
From: Yvan Fournier <yvan.fournier@noreply.edf.fr>
Date: Fri, 5 Jul 2024 22:27:03 +0200
Subject: [PATCH] Fix crash introduced by commit d6f5e853 (today).


diff --git a/src/base/cs_volume_mass_injection.c b/src/base/cs_volume_mass_injection.c
index ed8e40aca..1adbb12f2 100644
--- a/src/base/cs_volume_mass_injection.c
+++ b/src/base/cs_volume_mass_injection.c
@@ -756,16 +756,13 @@ cs_volume_mass_injection_get_arrays(const cs_field_t   *f,
   cs_volume_mass_injection_t *mi = _mass_injection;

   if (mi != NULL) {
-
     _ncesmp = mi->n_elts;
     _icetsm = mi->elt_id;

-  }
-
-  _volume_mass_injection_get_field_arrays(f->id, &_itpsmp, &_smcelp);
+    _volume_mass_injection_get_field_arrays(f->id, &_itpsmp, &_smcelp);

-  if (_ncesmp > 0) {
-    _volume_mass_injection_get_field_arrays(CS_F_(p)->id, NULL, &_gamma);
+    if (_ncesmp > 0)
+      _volume_mass_injection_get_field_arrays(CS_F_(p)->id, NULL, &_gamma);
   }

   if (ncesmp != NULL) *ncesmp = _ncesmp;
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Fix crash introduced by commit d6f5e853 (today).

Here is the root cause:
The bug was likely caused by improper handling of the conditional logic surrounding the checks for `mi` being `NULL` and `_ncesmp` being greater than zero. The removal of braces allowed critical function calls to execute even when certain conditions were not met, which could lead to accessing uninitialized data or skipping necessary operations, resulting in a crash.

Here is the patch:

 void
 cs_volume_mass_injection_get_arrays(const cs_field_t   *f,
                                     cs_lnum_t          *ncesmp,
                                     const cs_lnum_t   **icetsm,
                                     int               **itpsmp,
                                     cs_real_t         **smcelp,
                                     cs_real_t         **gamma)
 {
   cs_lnum_t  _ncesmp = 0;
   cs_lnum_t  *_icetsm = NULL;
   int        *_itpsmp = NULL;
   cs_real_t  *_smcelp = NULL;
   cs_real_t  *_gamma = NULL;

   cs_volume_mass_injection_t *mi = _mass_injection;

   if (mi != NULL) {
-
     _ncesmp = mi->n_elts;
     _icetsm = mi->elt_id;

-  }
-
-  _volume_mass_injection_get_field_arrays(f->id, &_itpsmp, &_smcelp);
+    _volume_mass_injection_get_field_arrays(f->id, &_itpsmp, &_smcelp);

-  if (_ncesmp > 0) {
-    _volume_mass_injection_get_field_arrays(CS_F_(p)->id, NULL, &_gamma);
+    if (_ncesmp > 0)
+      _volume_mass_injection_get_field_arrays(CS_F_(p)->id, NULL, &_gamma);
   }

   if (ncesmp != NULL) *ncesmp = _ncesmp;
   if (icetsm != NULL) *icetsm = _icetsm;
   if (itpsmp != NULL) *itpsmp = _itpsmp;
   if (smcelp != NULL) *smcelp = _smcelp;
   if (gamma != NULL) *gamma = _gamma;
 }



Provide a response strictly in the following format:

The code statements that lead to the bug are:
<text>
<text>
...
<text>
Reason:
<text>
The code statements that fix the bug are:
<text>
<text>
